{
  "category_edits": [
    {
      "category": "feature_construction",
      "rationale": "Apply the specified bounded rarity feature to history inputs across all four datasets using training-only item counts. Persist the fixed scales in each model checkpoint; preserve candidate embeddings, GRU topology, readout, loss, optimizer and training settings.",
      "edits": [
        {
          "find": "        self.item_emb = UnitNormItemEmbedding(itemnum + 1, hidden_units, padding_idx=0)\n        dropout = dropout_rate if num_layers > 1 else 0.0",
          "replace": "        self.item_emb = UnitNormItemEmbedding(itemnum + 1, hidden_units, padding_idx=0)\n        self.register_buffer(\"history_input_scale\", torch.ones(itemnum + 1))\n        self.history_input_scale[0] = 0.0\n        dropout = dropout_rate if num_layers > 1 else 0.0"
        },
        {
          "find": "        emb = self.dropout(self.item_emb(seq))",
          "replace": "        emb = self.dropout(\n            self.item_emb(seq) * self.history_input_scale[seq].unsqueeze(-1)\n        )"
        },
        {
          "find": "    optimizer = torch.optim.Adam(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY)",
          "replace": "    training_counts = np.zeros(itemnum + 1, dtype=np.float32)\n    for items in user_train.values():\n        np.add.at(training_counts, items, 1.0)\n    training_counts[0] = 0.0\n    log_counts = np.log1p(training_counts)\n    log_max = max(float(log_counts.max()), 1e-12)\n    history_scale = 1.0 + 0.02 * (1.0 - 2.0 * log_counts / log_max)\n    history_scale[0] = 0.0\n    with torch.no_grad():\n        model.history_input_scale.copy_(\n            torch.as_tensor(history_scale, dtype=model.history_input_scale.dtype, device=device)\n        )\n    optimizer = torch.optim.Adam(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY)"
        },
        {
          "find": "            \"sequence_readout\": \"gru_0.8_causal_mean_0.2_half_life_3\",",
          "replace": "            \"sequence_readout\": \"gru_0.8_causal_mean_0.2_half_life_3\",\n            \"history_input_feature\": \"training_log_frequency_centered_rarity_0.02\","
        },
        {
          "find": "        if meta.get(\"sequence_readout\") != \"gru_0.8_causal_mean_0.2_half_life_3\":\n            raise RuntimeError(f\"Incompatible GRU sequence readout for {ds}\")",
          "replace": "        if meta.get(\"sequence_readout\") != \"gru_0.8_causal_mean_0.2_half_life_3\":\n            raise RuntimeError(f\"Incompatible GRU sequence readout for {ds}\")\n        if meta.get(\"history_input_feature\") != \"training_log_frequency_centered_rarity_0.02\":\n            raise RuntimeError(f\"Incompatible GRU history input feature for {ds}\")"
        }
      ]
    }
  ],
  "change_summary": "Scale history inputs by training-only centered log-frequency rarity, keeping padding zero and candidate embeddings unchanged. Checkpoint the scales and synchronize the embedded predictor for all four category models."
}
